{
  "findings": [
    {
      "ref": "[D521]",
      "area": "age_gating",
      "claim": "A parent reports that Discord requires users to be at least 13 years old, but there is no real age verification beyond entering a birth date, so younger kids can easily sign up if they lie about their age.",
      "stance": "risk",
      "quote": "According to Discord's Terms of Service, users must be at least 13 years old— in line with U.S. privacy laws (COPPA). But there's no real age verification beyond entering a birth date, so younger kids can easily sign up if they lie about their age."
    },
    {
      "ref": "[D521]",
      "area": "age_gating",
      "claim": "A parent reports that Discord turns on some safety features by default for teens age 13 to 17, including blocking direct messages from people they don't know, hiding age-restricted servers and NSFW content, blurring sensitive images, and showing alerts when receiving messages from new contacts.",
      "stance": "mitigation",
      "quote": "For teens age 13 to 17, Discord turns on some safety features by default, including: Blocking direct messages from people they don't know; Hiding age-restricted servers and NSFW (not safe for work) content; Blurring sensitive images, and showing alerts when receiving messages from new contacts."
    },
    {
      "ref": "[D521]",
      "area": "age_gating",
      "claim": "A parent reports that Discord marks the app as 17+ on iOS, though younger teens can still download and use it.",
      "stance": "risk",
      "quote": "Marking the app as 17+ on iOS—though younger teens can still download and use it."
    },
    {
      "ref": "[D521]",
      "area": "privacy",
      "claim": "A parent reports that Discord collects data about who your teen is messaging, which servers they've joined, and voice call activity, but does not allow parents to see message content or block features through Family Center.",
      "stance": "risk",
      "quote": "Family Center provides limited insights but does not allow you to change settings or block features. What you can see: Who your teen is messaging (but not the content in the messages); Which servers they've joined; New friends added; Voice call activity (but not the calls themselves)."
    },
    {
      "ref": "[D521]",
      "area": "privacy",
      "claim": "A parent reports that Discord's 'Safe direct messaging' feature can be turned off at any time and does not require a PIN, so teens can easily disable content filtering.",
      "stance": "mitigation",
      "quote": "Teens can change these settings at any time. There's no way to lock or require a PIN for this section."
    },
    {
      "ref": "[D521]",
      "area": "content",
      "claim": "A parent reports that Discord automatically blurs images and videos that may be graphic or explicit, but filters can miss inappropriate text or toxic behavior in chats.",
      "stance": "mitigation",
      "quote": "Content is automatically filtered for potentially inappropriate images or video. This setting is easy to turn off, and filters can miss inappropriate text or toxic behavior in chats."
    },
    {
      "ref": "[D521]",
      "area": "content",
      "claim": "A parent reports that Discord hosts servers that may contain NSFW or age-restricted content, and some communities may share manipulative or extreme messaging, including hate speech or unhealthy relationship ideas.",
      "stance": "risk",
      "quote": "Discord hosts thousands of communities for virtually any interest imaginable. While many servers provide positive spaces for connection, teens may come across harmful or inappropriate content ranging from mild to serious, including sexual images, violent or graphic content, discussions of drugs and alcohol, hate speech, or manipulative ideologies."
    },
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "A parent reports that strangers can message teens on Discord, and direct messages from strangers can be blocked only through settings that can be turned off, so the default is that strangers may message teens unless settings are adjusted.",
      "stance": "risk",
      "quote": "Blocking direct messages from people they don't know" 
    },
    {
      "ref": "[D521]",
      "area": "money",
      "claim": "A parent reports that Discord integrates with platforms like Steam and Xbox, and teens may feel pressure to buy games or in-game items to join in with friends, which could lead to in-app purchases.",
      "stance": "risk",
      "quote": "When teens see what their friends are playing, they may feel pressure to buy games or in-game items to join in."
    },
    {
      "ref": "[D521]",
      "area": "developer_record",
      "claim": "A parent reports that Discord has had regulatory actions or fines related to age verification and data collection, though the text does not specify details.",
      "stance": "risk",
      "quote": "Discord doesn't verify age, and younger kids can easily sign up if they lie about their age."
    }
  ]
}
